  { SELECT ?id ?b (MAX(CONCAT(STR(?d),"|",?r,"|",COALESCE(STRAFTER(STR(?o),"outlook-"),""),"|",COALESCE(STRAFTER(STR(?w),"watch-"),""))) AS ?last) WHERE {
