      OPTIONAL{?x lad:outlook ?o} OPTIONAL{?x lad:watch ?w}
      ?e lad:sourceSystem ?s. FILTER(?s != "QA")
      OPTIONAL{?e lad:lei ?l} OPTIONAL{?c lad:lei ?l; lad:sourceSystem "RATINGS"}
      BIND(STRAFTER(STR(COALESCE(?c,?e)),"ladder/") AS ?id)
    } GROUP BY ?id ?b }
  BIND(STRAFTER(?last,"|") AS ?rest) BIND(STRBEFORE(?rest,"|") AS ?r)
  BIND(STRAFTER(?rest,"|") AS ?r2) BIND(STRBEFORE(?r2,"|") AS ?o) BIND(STRAFTER(?r2,"|") AS ?w)
  BIND(IF(?w="RWN","RWN",IF(?o="NEG" && ?r!="WD","NEG","x")) AS ?kind)
  FILTER(?kind != "x")
  BIND(FLOOR(xsd:integer(STRAFTER(?id,"E"))/100) AS ?bk)
} GROUP BY ?kind ?bk ORDER BY ?kind ?bk
